-- Vorrats-Aufgaben (rollend-3) in bestehende Flüge einfügen: 127 Aufgaben, 8 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (17, 'funktionen.linear', 777, 23, $auf$[{"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Gib Steigung und Achsenabschnitt der Geraden y = 4 − 3x an.", "schablone": "m = □; t = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-3, 4]}, "h": "m steht vor dem x, t steht allein. Die Reihenfolge im Term spielt keine Rolle.", "w": "Umgestellt: y = −3x + 4. Also m = −3 und t = 4.", "form": "bruecke", "zaehlt": "ja", "r": 778}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "A(1 | 2) und B(4 | 11) liegen auf einer Geraden. Nach rechts: 4 − 1 = ①. Nach oben: 11 − 2 = ②. Steigung: m = ② : ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [3, 9, 3]}, "h": "Steigung ist „nach oben“ geteilt durch „nach rechts“.", "w": "3 nach rechts, 9 nach oben: m = 9 : 3 = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 779}, {"l": "graph_ablesen", "t": "graph_ablesen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du zeichnest die Gerade y = 2x/3 − 1. Wie gehst du vor?"}, "a": ["−1 auf der y-Achse markieren, dann 3 nach rechts und 2 nach oben", "−1 auf der x-Achse markieren, dann 3 nach rechts und 2 nach oben", "bei (2 | 3) beginnen und 1 nach unten gehen", "−1 auf der y-Achse markieren, dann 2 nach rechts und 3 nach oben"], "o": {"index": 0}, "h": "Erst t auf der y-Achse, dann das Steigungsdreieck.", "w": "t = −1 liegt auf der y-Achse. m = 2/3: 3 nach rechts, 2 nach oben.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 780}, {"l": "lage", "t": "lage", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "g: y = 2x + 1. Welche Gerade steht senkrecht auf g?"}, "a": ["y = 2x − 3", "y = −2x + 1", "y = −0,5x + 4", "y = 0,5x + 1"], "o": {"index": 2}, "h": "Das Produkt der beiden Steigungen muss −1 sein.", "w": "2 · (−0,5) = −1. Also steht y = −0,5x + 4 senkrecht auf g.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 781}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "y = 2x + k. Was passiert mit der Geraden, wenn k größer wird?"}, "a": ["Sie wird steiler.", "Sie verschiebt sich nach oben.", "Sie dreht sich um den Ursprung.", "Sie wird flacher."], "o": {"index": 1}, "h": "Wo steht der Parameter: vor dem x oder allein?", "w": "k steht allein, es ist der Achsenabschnitt. Wird k größer, rutscht die ganze Gerade nach oben. Die Steigung 2 bleibt.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 782}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Geradenschar y = k · x + 2k − 1. Welche Gerade gehört zu k = 3? Gib Steigung und Achsenabschnitt an.", "schablone": "m = □; t = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 5]}, "h": "Ersetze jedes k durch 3.", "w": "y = 3x + 2 · 3 − 1 = 3x + 5.", "form": "bruecke", "zaehlt": "ja", "r": 783}, {"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "Die Gerade ist als 2y = 6x − 8 gegeben. Bringe sie in die Form y = m · x + t.", "schablone": "m = □; t = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, -4]}, "h": "Teile beide Seiten durch 2 – jeden Summanden.", "w": "y = 3x − 4. Also m = 3 und t = −4.", "form": "umkehren", "zaehlt": "ja", "r": 784}, {"l": "graph_ablesen", "t": "graph_ablesen", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Lies am Graphen die Steigung m und den Achsenabschnitt t ab.", "schablone": "m = □; t = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ).", "grafik": {"typ": "koordinaten", "x": [-4, 4], "y": [-5, 5], "graphen": [{"art": "linear", "m": -2, "t": 3, "name": "g"}]}}, "o": {"werte": [-2, 3]}, "h": "t liest du auf der y-Achse ab. Geh dann 1 nach rechts: Wie weit geht es nach oben oder unten?", "w": "Die Gerade schneidet die y-Achse bei 3. Bei 1 nach rechts geht es 2 nach unten: m = −2.", "form": "bruecke", "zaehlt": "ja", "r": 785}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Ursprungsgerade geht durch P(4 | 10). Für welches x ist y = 25?"}, "o": {"wert": 10}, "h": "Berechne zuerst k als y : x.", "w": "k = 10 : 4 = 2,5. Aus 2,5 · x = 25 folgt x = 10.", "form": "umkehren", "zaehlt": "ja", "r": 786}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Gerade durch P(2 | 7) mit m = 3. Weg A: Punkt einsetzen: 7 = 3 · 2 + t, also t = ①. Weg B: von P aus 2 nach links gehen: y sinkt dabei um ②, also t = 7 − ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1, 6]}, "h": "Beide Wege müssen dasselbe t ergeben.", "w": "7 = 6 + t, also t = 1. Weg B: 2 nach links heißt 2 · 3 = 6 nach unten: 7 − 6 = 1.", "form": "zwei_wege", "zaehlt": "ja", "r": 787}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Die Gerade geht durch A(1 | 4) und B(3 | 10). Bestimme m und t.", "schablone": "m = □; t = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 1]}, "h": "Erst m aus den zwei Punkten, dann einen Punkt einsetzen.", "w": "m = (10 − 4) : (3 − 1) = 3. Einsetzen von A: 4 = 3 · 1 + t, also t = 1.", "form": "anwenden", "zaehlt": "ja", "r": 788}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Schnittpunkt von g: y = 3x − 2 und h: y = −x + 14. Gleichsetzen: 3x − 2 = −x + 14. Plus x: ①x − 2 = 14. Plus 2: ①x = ②. Also x = ③ und y = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 16, 4, 10]}, "h": "Für den Schnittpunkt setzt du die Terme gleich.", "w": "4x − 2 = 14, 4x = 16, x = 4 und y = 3 · 4 − 2 = 10. Probe mit h: −4 + 14 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 789}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "g: y = 2x − 6. Wo schneidet g die x-Achse, und wo die y-Achse?", "schablone": "x-Achse: (□ | 0); y-Achse: (0 | □)", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, -6]}, "h": "Auf der x-Achse ist y = 0. Auf der y-Achse ist x = 0.", "w": "y = 0: 2x = 6, x = 3. x = 0: y = −6.", "form": "bruecke", "zaehlt": "ja", "r": 790}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Tank enthält 60 Liter. Pro Minute fließen 4 Liter ab. Welche Gleichung beschreibt den Inhalt y (in Litern) nach x Minuten?"}, "a": ["y = 4x + 60", "y = 60x − 4", "y = −4x + 60", "y = −60x + 4"], "o": {"index": 2}, "h": "t ist der Start, m die Änderung pro Minute.", "w": "Start 60, pro Minute 4 weniger: y = −4x + 60. Probe: nach 5 Minuten 60 − 20 = 40 Liter.", "form": "bruecke", "zaehlt": "ja", "r": 791}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "P(−2 | 5) und Q(2 | −3) liegen auf einer Geraden. Jan rechnet m = (5 − 3) : (2 − 2). Wie groß ist die Steigung wirklich?"}, "o": {"wert": -2}, "h": "Setze die negativen Koordinaten in Klammern.", "w": "m = (−3 − 5) : (2 − (−2)) = −8 : 4 = −2. Jan hat beide Minuszeichen weggelassen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 792}, {"l": "lage", "t": "lage", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Für welches k sind die Geraden y = (k + 1) · x − 2 und y = 4x + 5 parallel?"}, "o": {"wert": 3}, "h": "Parallele Geraden haben dieselbe Steigung.", "w": "k + 1 = 4, also k = 3.", "form": "umkehren", "zaehlt": "ja", "r": 793}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 3, "g": "parameter", "y": "luecken", "f": {"text": "Alle Geraden y = k · (x − 2) + 3 gehen durch einen gemeinsamen Punkt Z. Gib Z an.", "schablone": "Z(□ | □)", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 3]}, "h": "Für welches x hat k keinen Einfluss mehr?", "w": "Für x = 2 ist die Klammer 0. Dann ist y = 3, egal wie groß k ist. Z(2 | 3).", "form": "umkehren", "zaehlt": "ja", "r": 794}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tarif A kostet 10 € Grundgebühr und 2 € je Stunde. Tarif B hat keine Grundgebühr und kostet 4,50 € je Stunde. Ab wie vielen ganzen Stunden ist Tarif A billiger?"}, "o": {"wert": 5}, "h": "Wann sind beide gleich teuer?", "w": "Gleich teuer: 10 + 2x = 4,5x, also x = 4. Bei 4 Stunden kosten beide 18 €. Billiger ist A erst ab 5 Stunden (20 € gegen 22,50 €).", "form": "umkehren", "zaehlt": "ja", "r": 795}, {"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne m und t einer fallenden Geraden y = m · x + t, die die y-Achse oberhalb von 2 schneidet.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "Gerade fällt", "pruefe": ["<", "$1", 0], "zeige": "$1", "hinweis": "Dein m ist {}."}, {"name": "schneidet die y-Achse oberhalb von 2", "pruefe": [">", "$2", 2], "zeige": "$2", "hinweis": "Dein t ist {}."}], "beispiel": [-1, 5], "gut": [["-0,5", "2,1"]], "gegenbeispiele": [{"werte": [1, 5], "verletzt": "Gerade fällt"}, {"werte": [-1, 2], "verletzt": "schneidet die y-Achse oberhalb von 2"}, {"werte": [0, 3], "verletzt": "Gerade fällt"}]}, "h": "Welche Zahl entscheidet über Steigen oder Fallen, welche über den Schnitt mit der y-Achse?", "w": "Fallend heißt m negativ. Der Schnitt mit der y-Achse ist t. Zum Beispiel m = −1 und t = 5.", "form": "viele_antworten", "zaehlt": "ja", "r": 796}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne zwei Punkte mit ganzen Koordinaten und verschiedenen x-Werten, durch die eine Gerade mit der Steigung −3 geht. Reihenfolge der Felder: x und y des ersten Punkts, x und y des zweiten Punkts.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "verschiedene x-Werte", "pruefe": ["!=", "$1", "$3"], "hinweis": "Deine beiden Punkte haben denselben x-Wert."}, {"name": "Steigung ist −3", "pruefe": ["=", ["-", "$4", "$2"], ["*", -3, ["-", "$3", "$1"]]], "zeige": ["/", ["-", "$4", "$2"], ["-", "$3", "$1"]], "hinweis": "Die Steigung zwischen deinen Punkten ist {}."}], "beispiel": [0, 0, 1, -3], "gut": [[2, 5, 4, -1], [1, 1, -1, 7]], "gegenbeispiele": [{"werte": [1, 2, 1, 5], "verletzt": "verschiedene x-Werte"}, {"werte": [0, 0, 1, 3], "verletzt": "Steigung ist −3"}, {"werte": [0, 0, 3, -1], "verletzt": "Steigung ist −3"}]}, "h": "Was heißt Steigung −3 für einen Schritt nach rechts?", "w": "1 nach rechts, 3 nach unten: zum Beispiel (0 | 0) und (1 | −3).", "form": "viele_antworten", "zaehlt": "ja", "r": 797}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne m und t so, dass die Gerade y = m · x + t durch den Punkt P(2 | 5) geht und nicht waagrecht ist.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "nicht waagrecht", "pruefe": ["!=", "$1", 0], "hinweis": "Mit m = 0 ist die Gerade waagrecht."}, {"name": "geht durch P(2 | 5)", "pruefe": ["=", ["+", ["*", 2, "$1"], "$2"], 5], "zeige": ["+", ["*", 2, "$1"], "$2"], "hinweis": "Bei x = 2 hat deine Gerade den Wert {}."}], "beispiel": [1, 3], "gut": [[2, 1], [-1, 7], ["0,5", 4]], "gegenbeispiele": [{"werte": [0, 5], "verletzt": "nicht waagrecht"}, {"werte": [1, 4], "verletzt": "geht durch P(2 | 5)"}, {"werte": [2, 2], "verletzt": "geht durch P(2 | 5)"}]}, "h": "Setze x = 2 ein. Was muss herauskommen?", "w": "2m + t muss 5 sein. Zum Beispiel m = 1 und t = 3, oder m = 2 und t = 1.", "form": "viele_antworten", "zaehlt": "ja", "r": 798}, {"l": "lage", "t": "lage", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Nenne die Steigungen zweier Geraden, die senkrecht aufeinander stehen. Keine der beiden Steigungen soll 1 oder −1 sein.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "keine Steigung ist 1 oder −1", "pruefe": ["und", ["!=", ["betrag", "$1"], 1], ["!=", ["betrag", "$2"], 1]], "hinweis": "Eine deiner Steigungen ist 1 oder −1."}, {"name": "Geraden stehen senkrecht", "pruefe": ["=", ["*", "$1", "$2"], -1], "zeige": ["*", "$1", "$2"], "hinweis": "Das Produkt deiner Steigungen ist {}."}], "beispiel": [2, "-0,5"], "gut": [[-4, "0,25"], ["2/3", "-3/2"]], "gegenbeispiele": [{"werte": [1, -1], "verletzt": "keine Steigung ist 1 oder −1"}, {"werte": [2, "0,5"], "verletzt": "Geraden stehen senkrecht"}, {"werte": [2, -2], "verletzt": "Geraden stehen senkrecht"}]}, "h": "Was gilt für das Produkt der Steigungen senkrechter Geraden?", "w": "Das Produkt muss −1 sein: zum Beispiel 2 und −0,5, oder −4 und 0,25.", "form": "viele_antworten", "zaehlt": "ja", "r": 799}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "transfer", "y": "bedingung", "f": {"text": "Eine Kerze brennt gleichmäßig ab. Ihre Höhe nach x Stunden ist y = m · x + t (in cm). Nenne m und t so, dass die Kerze am Anfang höher als 10 cm ist und nach genau 6 Stunden abgebrannt ist.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "am Anfang höher als 10 cm", "pruefe": [">", "$2", 10], "zeige": "$2", "hinweis": "Am Anfang ist deine Kerze {} cm hoch."}, {"name": "nach 6 Stunden abgebrannt", "pruefe": ["=", ["+", ["*", 6, "$1"], "$2"], 0], "zeige": ["+", ["*", 6, "$1"], "$2"], "hinweis": "Nach 6 Stunden ist deine Kerze {} cm hoch."}], "beispiel": [-2, 12], "gut": [[-3, 18], ["-2,5", 15]], "gegenbeispiele": [{"werte": [-1, 6], "verletzt": "am Anfang höher als 10 cm"}, {"werte": [-2, 13], "verletzt": "nach 6 Stunden abgebrannt"}, {"werte": [2, 12], "verletzt": "nach 6 Stunden abgebrannt"}]}, "h": "t ist die Höhe am Anfang, m die Änderung pro Stunde. Abgebrannt heißt: Höhe 0.", "w": "6m + t = 0. Zum Beispiel t = 12 und m = −2: Die Kerze verliert 2 cm pro Stunde.", "form": "viele_antworten", "zaehlt": "ja", "r": 800}]$auf$::jsonb),
    (22, 'gleichungen.lgs2', 737, 21, $auf$[{"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ist das Zahlenpaar (3 | 2) eine Lösung des Systems I: x + y = 5 und II: 2x − y = 5?"}, "a": ["Ja, beide Gleichungen stimmen.", "Nein, nur Gleichung I stimmt.", "Nein, nur Gleichung II stimmt.", "Nein, keine der beiden stimmt."], "o": {"index": 1}, "h": "Setze das Paar in beide Gleichungen ein.", "w": "I: 3 + 2 = 5 stimmt. II: 2 · 3 − 2 = 4, nicht 5. Das Paar löst nur I, also nicht das System.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 738}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Die zwei Geraden eines Gleichungssystems sind parallel und verschieden. Was heißt das für die Lösung?"}, "a": ["Es gibt genau eine Lösung.", "Es gibt keine Lösung.", "Es gibt unendlich viele Lösungen."], "o": {"index": 1}, "h": "Die Lösung ist der Schnittpunkt.", "w": "Parallele, verschiedene Geraden haben keinen Schnittpunkt. Das System hat keine Lösung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 739}, {"l": "addition", "t": "addition", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "I: 3x + 2y = 12 und II: 5x − 2y = 4. Was entsteht, wenn du beide Gleichungen addierst?"}, "a": ["8x = 16", "4y = 16", "8x + 4y = 16", "8x = 8"], "o": {"index": 0}, "h": "Was passiert mit +2y und −2y?", "w": "2y und −2y sind Gegenzahlen und fallen weg. Links 3x + 5x = 8x, rechts 12 + 4 = 16.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 740}, {"l": "verfahren", "t": "verfahren", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "I: y = 4x − 1 und II: y = −x + 9. Welches Verfahren ist hier am geschicktesten?"}, "a": ["Gleichsetzen", "beide Gleichungen so addieren, wie sie dastehen", "erst beide Gleichungen mal 2 nehmen"], "o": {"index": 0}, "h": "Schau auf die Form der beiden Gleichungen.", "w": "Zweimal steht y = … da. Also die rechten Seiten gleichsetzen: 4x − 1 = −x + 9.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 741}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "I: y = 2x − 1 und II: 6x + y = 23. Einsetzen: 6x + (2x − 1) = 23. Zusammenfassen: ①x − 1 = 23. Also ①x = ②, x = ③ und y = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [8, 24, 3, 5]}, "h": "Steht y = … schon da, setzt du diesen Term ein.", "w": "8x − 1 = 23, also 8x = 24, x = 3 und y = 2 · 3 − 1 = 5. Probe in II: 6 · 3 + 5 = 23.", "form": "lueckenweg", "zaehlt": "nein", "r": 742}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Lies die Lösung des Gleichungssystems am Graphen ab.", "schablone": "x = □; y = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ).", "grafik": {"typ": "koordinaten", "x": [-3, 5], "y": [-2, 6], "graphen": [{"art": "linear", "m": 1, "t": 1, "name": "g"}, {"art": "linear", "m": -1, "t": 3, "name": "h"}]}}, "o": {"werte": [1, 2]}, "h": "Die Lösung ist der Schnittpunkt der beiden Geraden.", "w": "Die Geraden schneiden sich in (1 | 2). Probe: 1 + 1 = 2 und −1 + 3 = 2.", "form": "bruecke", "zaehlt": "ja", "r": 743}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "Das Paar (2 | −1) soll das System I: 3x + y = a und II: x − 2y = b lösen. Bestimme a und b.", "schablone": "a = □; b = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 4]}, "h": "Setze das Paar in beide Gleichungen ein.", "w": "I: 3 · 2 + (−1) = 5. II: 2 − 2 · (−1) = 2 + 2 = 4.", "form": "umkehren", "zaehlt": "ja", "r": 744}, {"l": "gleichsetzen", "t": "gleichsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Löse das System I: y = 3x − 5 und II: y = −2x + 10.", "schablone": "x = □; y = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 4]}, "h": "Zweimal y = …: Setze die Terme gleich.", "w": "3x − 5 = −2x + 10, also 5x = 15 und x = 3. Dann y = 3 · 3 − 5 = 4.", "form": "anwenden", "zaehlt": "ja", "r": 745}, {"l": "gleichsetzen", "t": "gleichsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "I: y = 2x + 3 und II: y = 5x − 6. Gleichsetzen: 2x + 3 = 5x − 6, also 9 = ①x und x = ②. Probe auf zwei Wegen: mit I ist y = ③, mit II ist y = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [3, 3, 9, 9]}, "h": "Beide Gleichungen müssen dasselbe y liefern.", "w": "9 = 3x, x = 3. I: 2 · 3 + 3 = 9. II: 5 · 3 − 6 = 9. Beide ergeben y = 9.", "form": "zwei_wege", "zaehlt": "ja", "r": 746}, {"l": "addition", "t": "addition", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "I: 2x + 3y = 13 und II: 4x − y = 5. Mit welcher Zahl nimmst du Gleichung II mal, damit beim Addieren y wegfällt?"}, "o": {"wert": 3}, "h": "Vor dem y sollen Gegenzahlen stehen.", "w": "In I steht +3y. Aus −y wird mit mal 3 genau −3y. Dann fällt y beim Addieren weg.", "form": "umkehren", "zaehlt": "ja", "r": 747}, {"l": "loesbarkeit", "t": "loesbarkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "I: 2x + y = 5 und II: 4x + 2y = 10. Wie viele Lösungen hat das System?"}, "a": ["keine", "genau eine", "unendlich viele"], "o": {"index": 2}, "h": "Vergleiche II mit dem Doppelten von I.", "w": "II ist genau das Doppelte von I. Beide Gleichungen sagen dasselbe; beim Lösen bleibt 0 = 0. Unendlich viele Lösungen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 748}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Im Zoo zahlen 2 Erwachsene und 3 Kinder zusammen 34 €. 1 Erwachsener und 1 Kind zahlen zusammen 14 €. Welches System passt? (e: Preis für einen Erwachsenen, k: Preis für ein Kind)"}, "a": ["2e + 3k = 14 und e + k = 34", "5 · (e + k) = 34 und e + k = 14", "2e · 3k = 34 und e · k = 14", "2e + 3k = 34 und e + k = 14"], "o": {"index": 3}, "h": "Für jede Angabe eine Gleichung.", "w": "Erste Angabe: 2e + 3k = 34. Zweite: e + k = 14. (Lösung: e = 8 €, k = 6 €.)", "form": "bruecke", "zaehlt": "ja", "r": 749}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "I: y = x + 4 und II: 2x − y = 3. Ben setzt ein und schreibt: 2x − x + 4 = 3. Welchen Wert hat x wirklich?"}, "o": {"wert": 7}, "h": "Der ganze Term x + 4 wird abgezogen. Was fehlt bei Ben?", "w": "Mit Klammer: 2x − (x + 4) = 3, also 2x − x − 4 = 3 und x = 7. Probe: y = 11, 14 − 11 = 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 750}, {"l": "loesbarkeit", "t": "loesbarkeit", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "I: 3x − y = 2 und II: 6x − 2y = c. Für welches c hat das System unendlich viele Lösungen?"}, "o": {"wert": 4}, "h": "II muss dasselbe sagen wie I.", "w": "Das Doppelte von I ist 6x − 2y = 4. Für c = 4 sind beide Gleichungen gleichwertig.", "form": "umkehren", "zaehlt": "ja", "r": 751}, {"l": "loesung_parameter", "t": "loesung_parameter", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Beim Lösen eines Gleichungssystems bleibt (k − 3) · x = 6 übrig. Für welches k hat das System keine Lösung?"}, "o": {"wert": 3}, "h": "Wann darfst du nicht durch k − 3 teilen?", "w": "Für k = 3 steht da 0 · x = 6. Das ist für kein x wahr: keine Lösung.", "form": "umkehren", "zaehlt": "ja", "r": 752}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Stall sind Hühner und Kaninchen: zusammen 20 Tiere mit 56 Beinen. Wie viele Kaninchen sind es?"}, "o": {"wert": 8}, "h": "Für jede gesuchte Zahl eine Variable: h Hühner, k Kaninchen.", "w": "h + k = 20 und 2h + 4k = 56. Wären alle Hühner, gäbe es 40 Beine. Die 16 Beine mehr gehören zu 8 Kaninchen.", "form": "anwenden", "zaehlt": "ja", "r": 753}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne ein Zahlenpaar (x | y), das die Gleichung 2x + y = 7 löst, aber die Gleichung x − y = 2 nicht.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "löst 2x + y = 7", "pruefe": ["=", ["+", ["*", 2, "$1"], "$2"], 7], "zeige": ["+", ["*", 2, "$1"], "$2"], "hinweis": "Bei dir ist 2x + y = {}."}, {"name": "löst x − y = 2 nicht", "pruefe": ["!=", ["-", "$1", "$2"], 2], "hinweis": "Dein Paar löst auch die zweite Gleichung."}], "beispiel": [1, 5], "gut": [[0, 7], ["2,5", 2]], "gegenbeispiele": [{"werte": [1, 4], "verletzt": "löst 2x + y = 7"}, {"werte": [3, 1], "verletzt": "löst x − y = 2 nicht"}]}, "h": "Wähle ein x und rechne das passende y aus.", "w": "Zum Beispiel (1 | 5): 2 + 5 = 7, und 1 − 5 = −4 ist nicht 2. Nur (3 | 1) löst beide.", "form": "viele_antworten", "zaehlt": "ja", "r": 754}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "bedingung", "f": {"text": "Karten für Erwachsene kosten 6 €, für Kinder 4 €. Eine Gruppe zahlt zusammen genau 40 €. Nenne eine mögliche Zahl von Erwachsenen und von Kindern (jeweils mindestens 1).", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "jeweils mindestens 1", "pruefe": [">=", ["min", "$alle"], 1], "zeige": ["min", "$alle"], "hinweis": "Deine kleinere Zahl ist {}."}, {"name": "zusammen 40 €", "pruefe": ["=", ["+", ["*", 6, "$1"], ["*", 4, "$2"]], 40], "zeige": ["+", ["*", 6, "$1"], ["*", 4, "$2"]], "hinweis": "Deine Gruppe zahlt {} €."}], "beispiel": [4, 4], "gut": [[2, 7], [6, 1]], "gegenbeispiele": [{"werte": [0, 10], "verletzt": "jeweils mindestens 1"}, {"werte": [4, 3], "verletzt": "zusammen 40 €"}, {"werte": [3, 5], "verletzt": "zusammen 40 €"}]}, "h": "Stelle eine Gleichung mit zwei Variablen auf.", "w": "6e + 4k = 40. Es passen 2 Erwachsene und 7 Kinder, 4 und 4 oder 6 und 1.", "form": "viele_antworten", "zaehlt": "ja", "r": 755}, {"l": "loesbarkeit", "t": "loesbarkeit", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Ergänze Gleichung II so, dass das System keine Lösung hat. I: 2x + y = 3, II: 4x + □ · y = □.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "nicht genau eine Lösung", "pruefe": ["=", "$1", 2], "hinweis": "Mit deiner Zahl vor dem y hat das System genau eine Lösung."}, {"name": "nicht unendlich viele Lösungen", "pruefe": ["!=", "$2", 6], "hinweis": "Mit deinen Zahlen ist II das Doppelte von I: unendlich viele Lösungen."}], "beispiel": [2, 5], "gut": [[2, 0], [2, "6,5"]], "gegenbeispiele": [{"werte": [1, 5], "verletzt": "nicht genau eine Lösung"}, {"werte": [2, 6], "verletzt": "nicht unendlich viele Lösungen"}, {"werte": [-2, 6], "verletzt": "nicht genau eine Lösung"}]}, "h": "Vergleiche II mit dem Doppelten von I.", "w": "Das Doppelte von I ist 4x + 2y = 6. Steht links dasselbe, rechts aber eine andere Zahl, widersprechen sich die Gleichungen: zum Beispiel 4x + 2y = 5.", "form": "viele_antworten", "zaehlt": "ja", "r": 756}, {"l": "addition", "t": "addition", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Baue ein Gleichungssystem mit genau einer Lösung, nämlich (2 | 3). I: x + y = □ und II: □ · x − y = □. Die Zahl vor dem x soll nicht 0 sein.", "felder": [{"art": "rational"}, {"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "Gleichung I stimmt für (2 | 3)", "pruefe": ["=", "$1", 5], "hinweis": "Mit (2 | 3) hat die linke Seite von I den Wert 5."}, {"name": "Zahl vor dem x ist nicht 0", "pruefe": ["!=", "$2", 0], "hinweis": "Die Zahl vor dem x soll nicht 0 sein."}, {"name": "Gleichung II stimmt für (2 | 3)", "pruefe": ["=", ["-", ["*", 2, "$2"], 3], "$3"], "zeige": ["-", ["*", 2, "$2"], 3], "hinweis": "Mit (2 | 3) hat die linke Seite von II den Wert {}."}, {"name": "genau eine Lösung", "pruefe": ["!=", "$2", -1], "hinweis": "Mit dieser Zahl vor dem x hat dein System nicht genau eine Lösung."}], "beispiel": [5, 2, 1], "gut": [[5, 1, -1], [5, "0,5", -2]], "gegenbeispiele": [{"werte": [6, 2, 1], "verletzt": "Gleichung I stimmt für (2 | 3)"}, {"werte": [5, 0, -3], "verletzt": "Zahl vor dem x ist nicht 0"}, {"werte": [5, 2, 2], "verletzt": "Gleichung II stimmt für (2 | 3)"}, {"werte": [5, -1, -5], "verletzt": "genau eine Lösung"}]}, "h": "Setze (2 | 3) in beide Gleichungen ein.", "w": "I: 2 + 3 = 5. II: zum Beispiel 2x − y = 1, denn 4 − 3 = 1. Addieren ergibt 3x = 6, also x = 2.", "form": "viele_antworten", "zaehlt": "ja", "r": 757}, {"l": "loesung_parameter", "t": "loesung_parameter", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "I: y = k · x + 2 und II: y = 3x + c. Nenne k und c so, dass das System genau eine Lösung hat und diese bei x = 1 liegt.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "genau eine Lösung", "pruefe": ["!=", "$1", 3], "hinweis": "Mit deinem k hat das System nicht genau eine Lösung."}, {"name": "Lösung liegt bei x = 1", "pruefe": ["=", ["+", "$1", 2], ["+", 3, "$2"]], "zeige": ["+", "$1", 2], "hinweis": "Bei x = 1 liefert I den Wert {}. II liefert etwas anderes."}], "beispiel": [5, 4], "gut": [[1, 0], ["-2", "-3"]], "gegenbeispiele": [{"werte": [3, 2], "verletzt": "genau eine Lösung"}, {"werte": [5, 3], "verletzt": "Lösung liegt bei x = 1"}, {"werte": [0, 0], "verletzt": "Lösung liegt bei x = 1"}]}, "h": "Setze x = 1 in beide Gleichungen ein. Was muss gelten?", "w": "Bei x = 1 müssen beide dasselbe y liefern: k + 2 = 3 + c. Zum Beispiel k = 5 und c = 4. Für k = 3 wären die Geraden parallel.", "form": "viele_antworten", "zaehlt": "ja", "r": 758}]$auf$::jsonb),
    (49, 'geometrie.winkel', 559, 20, $auf$[{"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein rechter Winkel wird in zwei Teile geteilt. Ein Teil hat 37°, der andere 90° − 37° = ①°. Ein gestreckter Winkel wird in zwei Teile geteilt. Ein Teil hat 37°, der andere ②°. Beide anderen Teile zusammen: ① + ② = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [53, 143, 196]}, "h": "Das Ganze ist erst 90°, dann 180°.", "w": "90 − 37 = 53. 180 − 37 = 143. 53 + 143 = 196.", "form": "lueckenweg", "zaehlt": "nein", "r": 560}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel hat 65°. Sein Nebenwinkel hat 180° − 65° = ①°. Der Winkel gegenüber vom Nebenwinkel ist genauso groß. Er ist um ① − 65° = ②° größer als der gegebene Winkel. Alle vier Winkel zusammen: 2 · 65° + 2 · ①° = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [115, 50, 360]}, "h": "Gegenüberliegende Winkel sind gleich. Nachbarwinkel ergeben zusammen 180°.", "w": "180 − 65 = 115. 115 − 65 = 50. 2 · 65 + 2 · 115 = 360.", "form": "lueckenweg", "zaehlt": "nein", "r": 561}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Zwei Winkel liegen nebeneinander an einer Geraden und bilden zusammen einen gestreckten Winkel. Einer ist bekannt. Wie findest du den anderen?"}, "a": ["90° minus den bekannten Winkel", "Er ist gleich groß.", "180° minus den bekannten Winkel", "360° minus den bekannten Winkel"], "o": {"index": 2}, "h": "Wie groß ist ein gestreckter Winkel?", "w": "Ein gestreckter Winkel hat 180°. Der fehlende Winkel ist 180° minus der bekannte.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 562}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel hat 50°. Ole sagt: „Dann hat der Winkel direkt daneben auch 50°.“ Was stimmt?"}, "a": ["Ole hat recht.", "Der Winkel daneben hat 40°.", "Alle vier Winkel haben 90°.", "Der Winkel daneben hat 130°. 50° hat der gegenüberliegende Winkel."], "o": {"index": 3}, "h": "Welche Winkel an einer Kreuzung sind gleich groß?", "w": "Gleich groß sind die gegenüberliegenden Winkel. Nachbarwinkel ergeben 180°: 180° − 50° = 130°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 563}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du willst die Behauptung „Gegenüberliegende Winkel an einer Kreuzung sind immer spitz“ widerlegen. Was genügt?"}, "a": ["ein Gegenbeispiel: zwei Geraden, bei denen ein Winkel 120° hat", "viele Beispiele mit spitzen Winkeln", "die Definition: Ein spitzer Winkel ist kleiner als 90°"], "o": {"index": 0}, "h": "Was braucht man, um „immer“ zu widerlegen?", "w": "Ein einziges Gegenbeispiel genügt: Hat ein Winkel 120°, dann hat der gegenüberliegende auch 120° – und das ist nicht spitz.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 564}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Um einen Punkt liegen vier Winkel: drei gleich große und einer mit 60°. Wie groß ist jeder der drei gleichen Winkel?"}, "o": {"wert": 100, "einheit": "°"}, "h": "Alle Winkel um einen Punkt ergeben zusammen 360°.", "w": "360° − 60° = 300°. Geteilt durch 3: 100°.", "form": "umkehren", "zaehlt": "ja", "r": 565}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Auf einer Seite einer Geraden liegen drei Winkel nebeneinander: 40°, ein unbekannter und 85°. Weg A: 180° − 40° − 85°. Weg B: erst 40° + 85° = ①°, dann 180° − ①° = ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [125, 55]}, "h": "Beide Wege müssen denselben Winkel ergeben.", "w": "40° + 85° = 125°. 180° − 125° = 55°. Weg A: 180° − 40° = 140°, 140° − 85° = 55°.", "form": "zwei_wege", "zaehlt": "ja", "r": 566}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Minutenzeiger einer Uhr hat sich um 150° gedreht. Wie viele Minuten sind vergangen?"}, "o": {"wert": 25, "einheit": "min"}, "h": "Um wie viel Grad dreht sich der Minutenzeiger in einer Minute?", "w": "In 60 Minuten 360°, also 6° je Minute. 150° : 6° = 25 Minuten.", "form": "umkehren", "zaehlt": "ja", "r": 567}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Du schaust nach Norden und drehst dich im Uhrzeigersinn um 135°. In welche Richtung schaust du jetzt?"}, "a": ["Osten", "Südosten", "Süden", "Südwesten"], "o": {"index": 1}, "h": "Zwischen zwei Nachbarrichtungen liegen 45°.", "w": "135° sind drei Schritte von 45°: Nordosten, Osten, Südosten.", "form": "bruecke", "zaehlt": "ja", "r": 568}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Du schaust nach Westen und drehst dich auf dem kürzesten Weg nach Nordosten. Um wie viel Grad drehst du dich?"}, "o": {"wert": 135, "einheit": "°"}, "h": "Zähle die Schritte: Westen, Nordwesten, Norden, Nordosten.", "w": "Drei Schritte von je 45°: 135°.", "form": "umkehren", "zaehlt": "ja", "r": 569}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einem Rechteck teilt die Diagonale eine Ecke in zwei Winkel. Einer hat 28°. Wie groß ist der andere?"}, "o": {"wert": 62, "einheit": "°"}, "h": "Wie groß ist jede Ecke im Rechteck?", "w": "Jede Ecke hat 90°. 90° − 28° = 62°.", "form": "anwenden", "zaehlt": "ja", "r": 570}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel ist um 40° größer als sein Nachbarwinkel. Wie groß ist der kleinere der beiden?"}, "o": {"wert": 70, "einheit": "°"}, "h": "Beide zusammen ergeben 180°.", "w": "Kleiner Winkel x, großer x + 40°. Zusammen 2x + 40° = 180°, also x = 70°.", "form": "umkehren", "zaehlt": "ja", "r": 571}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Es ist 3:30 Uhr. Kim sagt: „Der Stundenzeiger steht auf der 3, der Minutenzeiger auf der 6. Der Winkel ist 90°.“ Wie groß ist der Winkel zwischen den Zeigern wirklich?"}, "o": {"wert": 75, "einheit": "°"}, "h": "Bleibt der Stundenzeiger eine halbe Stunde lang auf der 3 stehen?", "w": "In 30 Minuten wandert der Stundenzeiger 15° weiter Richtung 4. Der Winkel ist 90° − 15° = 75°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 572}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Ecke eines Quadrats wird durch zwei Linien in drei Winkel geteilt. Der mittlere ist doppelt so groß wie jeder der beiden äußeren. Wie groß ist der mittlere Winkel?"}, "o": {"wert": 45, "einheit": "°"}, "h": "Die drei Teile ergeben zusammen 90°. Wie viele „äußere Winkel“ sind das?", "w": "Äußerer Winkel x, mittlerer 2x: x + 2x + x = 90°, also x = 22,5°. Der mittlere hat 45°.", "form": "umkehren", "zaehlt": "ja", "r": 573}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Behauptung: „Zwei Winkel, die zusammen 180° ergeben, sind immer gleich groß.“ Was stimmt?"}, "a": ["Das stimmt immer.", "Das stimmt nie.", "Das stimmt nicht immer: 70° und 110° ergeben 180° und sind verschieden.", "Das stimmt, denn 90° + 90° = 180°."], "o": {"index": 2}, "h": "Suche ein Gegenbeispiel.", "w": "70° + 110° = 180°, aber 70° ist nicht 110°. Ein Gegenbeispiel genügt. Gleich groß sind sie nur bei 90° und 90°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 574}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne zwei verschiedene Winkel (ganze Grad), die zusammen einen rechten Winkel ergeben. Beide sollen größer als 20° sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "beide größer als 20°", "pruefe": [">", ["min", "$alle"], 20], "zeige": ["min", "$alle"], "hinweis": "Dein kleinerer Winkel hat {}°."}, {"name": "verschieden", "pruefe": ["verschieden", "$alle"], "hinweis": "Die zwei Winkel sollen verschieden sein."}, {"name": "zusammen ein rechter Winkel", "pruefe": ["=", ["summe", "$alle"], 90], "zeige": ["summe", "$alle"], "hinweis": "Deine Winkel ergeben zusammen {}°."}], "beispiel": [30, 60], "gut": [[21, 69], [50, 40]], "gegenbeispiele": [{"werte": [10, 80], "verletzt": "beide größer als 20°"}, {"werte": [45, 45], "verletzt": "verschieden"}, {"werte": [30, 70], "verletzt": "zusammen ein rechter Winkel"}]}, "h": "Wie groß ist ein rechter Winkel?", "w": "Ein rechter Winkel hat 90°. Zum Beispiel 30° und 60°.", "form": "viele_antworten", "zaehlt": "ja", "r": 575}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Zwei Geraden schneiden sich. Nenne die vier Winkel der Reihe nach im Kreis herum. Der erste soll stumpf sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "erster Winkel stumpf", "pruefe": ["und", [">", "$1", 90], ["<", "$1", 180]], "zeige": "$1", "hinweis": "Dein erster Winkel hat {}°."}, {"name": "gegenüberliegende Winkel passen", "pruefe": ["und", ["=", "$1", "$3"], ["=", "$2", "$4"]], "hinweis": "Bei dir sind gegenüberliegende Winkel nicht gleich groß."}, {"name": "Nachbarwinkel passen", "pruefe": ["=", ["+", "$1", "$2"], 180], "zeige": ["+", "$1", "$2"], "hinweis": "Dein erster und dein zweiter Winkel ergeben zusammen {}°."}], "beispiel": [120, 60, 120, 60], "gut": [[91, 89, 91, 89]], "gegenbeispiele": [{"werte": [60, 120, 60, 120], "verletzt": "erster Winkel stumpf"}, {"werte": [120, 60, 110, 70], "verletzt": "gegenüberliegende Winkel passen"}, {"werte": [120, 70, 120, 70], "verletzt": "Nachbarwinkel passen"}]}, "h": "Der erste und der dritte Winkel liegen sich gegenüber.", "w": "Zum Beispiel 120°, 60°, 120°, 60°: Gegenüber gleich, nebeneinander zusammen 180°.", "form": "viele_antworten", "zaehlt": "ja", "r": 576}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "bedingung", "f": {"text": "Nenne drei verschiedene Winkel (ganze Grad), die zusammen genau um einen Punkt herum passen. Einer davon soll überstumpf sein, also größer als 180°.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "jeder Winkel größer als 0°", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Dein kleinster Winkel hat {}°."}, {"name": "verschieden", "pruefe": ["verschieden", "$alle"], "hinweis": "Die drei Winkel sollen verschieden sein."}, {"name": "passen genau um einen Punkt", "pruefe": ["=", ["summe", "$alle"], 360], "zeige": ["summe", "$alle"], "hinweis": "Deine Winkel ergeben zusammen {}°."}, {"name": "einer ist überstumpf", "pruefe": ["=", ["anzahl_positiv", ["liste", ["-", "$1", 180], ["-", "$2", 180], ["-", "$3", 180]]], 1], "zeige": ["max", "$alle"], "hinweis": "Dein größter Winkel hat {}°."}], "beispiel": [200, 100, 60], "gut": [[181, 100, 79]], "gegenbeispiele": [{"werte": [200, 170, -10], "verletzt": "jeder Winkel größer als 0°"}, {"werte": [200, 80, 80], "verletzt": "verschieden"}, {"werte": [200, 100, 50], "verletzt": "passen genau um einen Punkt"}, {"werte": [150, 120, 90], "verletzt": "einer ist überstumpf"}]}, "h": "Wie viel Grad hat der volle Winkel?", "w": "Zusammen 360°. Zum Beispiel 200°, 100° und 60°.", "form": "viele_antworten", "zaehlt": "ja", "r": 577}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne eine volle Stunde (1 bis 12), zu der der kleinere Winkel zwischen den beiden Zeigern größer als 90° ist, aber kein gestreckter Winkel.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "volle Stunde von 1 bis 12", "pruefe": ["und", [">=", "$1", 1], ["<=", "$1", 12]], "zeige": "$1", "hinweis": "Deine Zahl ist {}."}, {"name": "Winkel größer als 90°", "pruefe": [">", ["min", ["liste", ["*", 30, "$1"], ["-", 360, ["*", 30, "$1"]]]], 90], "zeige": ["min", ["liste", ["*", 30, "$1"], ["-", 360, ["*", 30, "$1"]]]], "hinweis": "Zu deiner Uhrzeit ist der Winkel {}°."}, {"name": "kein gestreckter Winkel", "pruefe": ["!=", ["min", ["liste", ["*", 30, "$1"], ["-", 360, ["*", 30, "$1"]]]], 180], "zeige": ["min", ["liste", ["*", 30, "$1"], ["-", 360, ["*", 30, "$1"]]]], "hinweis": "Zu deiner Uhrzeit ist der Winkel {}° – das ist ein gestreckter Winkel."}], "beispiel": [4], "gut": [[5], [7], [8]], "gegenbeispiele": [{"werte": [13], "verletzt": "volle Stunde von 1 bis 12"}, {"werte": [3], "verletzt": "Winkel größer als 90°"}, {"werte": [6], "verletzt": "kein gestreckter Winkel"}, {"werte": [11], "verletzt": "Winkel größer als 90°"}]}, "h": "Zwischen zwei Zahlen auf der Uhr liegen 30°.", "w": "Um 4 Uhr sind es 4 · 30° = 120°. Es passen 4, 5, 7 und 8 Uhr.", "form": "viele_antworten", "zaehlt": "ja", "r": 578}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "bedingung", "f": {"text": "Du drehst dich zweimal nacheinander im Uhrzeigersinn. Jede Drehung ist ein Vielfaches von 45°, größer als 0° und kleiner als 360°. Die erste Drehung ist kleiner als die zweite. Am Ende schaust du genau in die Gegenrichtung. Nenne beide Drehungen in Grad.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "Vielfache von 45° zwischen 0° und 360°", "pruefe": ["und", ["teilbar", "$1", 45], ["teilbar", "$2", 45], [">", ["min", "$alle"], 0], ["<", ["max", "$alle"], 360]], "hinweis": "Jede Drehung soll ein Vielfaches von 45° sein, größer als 0° und kleiner als 360°."}, {"name": "erste Drehung kleiner als die zweite", "pruefe": ["<", "$1", "$2"], "hinweis": "Deine erste Drehung ist nicht kleiner als die zweite."}, {"name": "am Ende Gegenrichtung", "pruefe": ["oder", ["=", ["summe", "$alle"], 180], ["=", ["summe", "$alle"], 540]], "zeige": ["summe", "$alle"], "hinweis": "Zusammen drehst du dich um {}°."}], "beispiel": [45, 135], "gut": [[225, 315]], "gegenbeispiele": [{"werte": [40, 140], "verletzt": "Vielfache von 45° zwischen 0° und 360°"}, {"werte": [135, 45], "verletzt": "erste Drehung kleiner als die zweite"}, {"werte": [45, 90], "verletzt": "am Ende Gegenrichtung"}, {"werte": [90, 90], "verletzt": "erste Drehung kleiner als die zweite"}]}, "h": "Um wie viel Grad muss man sich insgesamt drehen, um in die Gegenrichtung zu schauen?", "w": "Insgesamt 180° (oder eine volle Drehung mehr: 540°). Zum Beispiel 45° und 135°.", "form": "viele_antworten", "zaehlt": "ja", "r": 579}]$auf$::jsonb),
    (51, 'messen.flaechen', 588, 20, $auf$[{"l": "einheitsquadrate", "t": "einheitsquadrate", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Rechteck ist 7 cm lang. Du legst es mit Quadraten von 1 cm² in waagerechten Reihen übereinander aus: Jede Reihe hat 7 Quadrate. Insgesamt brauchst du 28 Quadrate. Dann sind es 28 : 7 = ① Reihen. Das Rechteck ist ① cm hoch. Sein Umfang ist 2 · 7 + 2 · ① = ② cm.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 22]}, "h": "Wie viele Quadrate passen in eine Reihe, wie viele Reihen übereinander?", "w": "28 : 7 = 4 Reihen, das Rechteck ist 4 cm hoch. Umfang: 14 + 8 = 22 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 589}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "1 m² = ① dm², also 3 m² = 3 · ① = ② dm². Ebenso gilt 1 dm² = ③ cm². Also sind 3 m² gleich ② · ③ = ④ cm².", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [100, 300, 100, 30000]}, "h": "Bei Längen ist die Umrechnungszahl 10. Bei Flächen kommt sie zweimal vor.", "w": "1 m² = 100 dm², 3 m² = 300 dm². 1 dm² = 100 cm². 300 · 100 = 30 000 cm².", "form": "lueckenweg", "zaehlt": "nein", "r": 590}, {"l": "einheitsquadrate", "t": "einheitsquadrate", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein Rechteck ist 5 cm lang und 3 cm breit. Pia rechnet 5 + 3 + 5 + 3 = 16 und sagt: „Die Fläche ist 16 cm².“ Was ist falsch?"}, "a": ["Nichts.", "Sie hat sich verrechnet: Es sind 18 cm².", "Sie hat den Umfang berechnet. Die Fläche ist 15 cm².", "Die Fläche ist 8 cm²."], "o": {"index": 2}, "h": "Was misst man, wenn man alle Seiten zusammenzählt?", "w": "Alle Seiten zusammen sind der Umfang: 16 cm. Die Fläche ist 5 · 3 = 15 cm².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 591}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Warum ist die Umrechnungszahl bei Flächen 100 und nicht 10?"}, "a": ["Weil Flächen größer sind als Längen.", "Weil 1 dm = 100 cm ist.", "Weil in ein Quadrat mit 1 dm Seitenlänge 10 Reihen mit je 10 Quadraten von 1 cm² passen.", "Das ist nur eine Abmachung."], "o": {"index": 2}, "h": "Lege in Gedanken ein Quadrat von 1 dm² mit Zentimeter-Quadraten aus.", "w": "1 dm = 10 cm. In das Quadrat passen 10 Reihen mit je 10 Quadraten: 100 cm².", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 592}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Für welche Aufgabe brauchst du den Umfang?"}, "a": ["Rasen für einen Garten säen", "Einen Zaun um den Garten bauen", "Farbe für eine Wand kaufen", "Fliesen für den Boden zählen"], "o": {"index": 1}, "h": "Geht es um den Rand oder um das, was innen liegt?", "w": "Der Zaun läuft außen um den Garten herum: Umfang. Rasen, Farbe und Fliesen bedecken eine Fläche.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 593}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Rechteck hat die Fläche 48 cm² und ist 8 cm lang. Wie groß ist sein Umfang?"}, "o": {"wert": 28, "einheit": "cm"}, "h": "Berechne zuerst die Breite.", "w": "Breite: 48 : 8 = 6 cm. Umfang: 2 · 8 + 2 · 6 = 28 cm.", "form": "umkehren", "zaehlt": "ja", "r": 594}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Schreibe 4 m² 6 dm² als Kommazahl in m²."}, "o": {"wert": 4.06, "einheit": "m²"}, "h": "Bei Flächen bekommt jede kleinere Einheit zwei Stellen.", "w": "6 dm² = 0,06 m². Also 4,06 m².", "form": "bruecke", "zaehlt": "ja", "r": 595}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "umkehr", "y": "luecken", "f": {"text": "2,35 a = 2 a ① m². Und 0,08 m² = ② dm².", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [35, 8]}, "h": "Die zwei Stellen hinter dem Komma gehören zur nächstkleineren Einheit.", "w": "2,35 a = 2 a 35 m². 0,08 m² = 8 dm².", "form": "bruecke", "zaehlt": "ja", "r": 596}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Aus einem Rechteck von 8 m mal 6 m wird an einer Ecke ein Rechteck von 3 m mal 2 m herausgeschnitten. Weg A (ergänzen und abziehen): 48 m² − ① m² = ② m². Weg B (zerlegen): 8 m · 4 m + 5 m · 2 m.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [6, 42]}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Herausgeschnitten: 3 · 2 = 6 m². 48 − 6 = 42 m². Weg B: 32 + 10 = 42 m².", "form": "zwei_wege", "zaehlt": "ja", "r": 597}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zimmer ist 5 m lang und 3,5 m breit. Ringsum kommt eine Fußleiste, nur an der 1 m breiten Tür nicht. Wie viele Meter Leiste braucht man?"}, "o": {"wert": 16, "einheit": "m"}, "h": "Die Leiste läuft am Rand entlang.", "w": "Umfang: 2 · 5 m + 2 · 3,5 m = 17 m. Ohne die Tür: 16 m.", "form": "anwenden", "zaehlt": "ja", "r": 598}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Wand ist 5 m lang und 2,4 m hoch. Ein Eimer Farbe reicht für 6 m². Wie viele Eimer braucht man?"}, "o": {"wert": 2}, "h": "Berechne erst die Fläche der Wand.", "w": "5 m · 2,4 m = 12 m². 12 : 6 = 2 Eimer.", "form": "anwenden", "zaehlt": "ja", "r": 599}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quadrat hat den Umfang 36 cm. Wie groß ist seine Fläche?"}, "o": {"wert": 81, "einheit": "cm²"}, "h": "Wie lang ist eine Seite?", "w": "Eine Seite: 36 : 4 = 9 cm. Fläche: 9 · 9 = 81 cm².", "form": "umkehren", "zaehlt": "ja", "r": 600}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Ein Bilderrahmen ist außen 10 cm mal 8 cm groß. Innen ist ein Rechteck von 6 cm mal 4 cm ausgeschnitten. Tim rechnet 10 · 8 + 6 · 4. Wie viele cm² hat der Rahmen wirklich?"}, "o": {"wert": 56, "einheit": "cm²"}, "h": "Gehört das Loch zum Rahmen?", "w": "Das ausgeschnittene Stück wird abgezogen: 80 − 24 = 56 cm².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 601}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Zwei Rechtecke haben beide den Umfang 20 cm. Das eine ist 9 cm lang, das andere 5 cm. Um wie viele cm² unterscheiden sich ihre Flächen?"}, "o": {"wert": 16, "einheit": "cm²"}, "h": "Berechne zu jeder Länge erst die Breite.", "w": "Länge plus Breite ist 10 cm. Erstes: 9 · 1 = 9 cm². Zweites: 5 · 5 = 25 cm². Unterschied: 16 cm².", "form": "bruecke", "zaehlt": "ja", "r": 602}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Bei einem Rechteck werden die Länge und die Breite beide verdoppelt. Lars sagt: „Dann ist auch die Fläche doppelt so groß.“ Was stimmt?"}, "a": ["Lars hat recht.", "Die Fläche wird viermal so groß, denn 2a · 2b = 4 · a · b.", "Die Fläche bleibt gleich.", "Die Fläche wird achtmal so groß."], "o": {"index": 1}, "h": "Probiere es mit einem Rechteck von 3 cm mal 2 cm.", "w": "3 · 2 = 6 cm². Verdoppelt: 6 · 4 = 24 cm². Das ist das Vierfache.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 603}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne Länge und Breite (ganze Zentimeter) eines Rechtecks mit der Fläche 36 cm², das kein Quadrat ist.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "beide Seiten größer als 0", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Deine kürzere Seite ist {} cm."}, {"name": "kein Quadrat", "pruefe": ["verschieden", "$alle"], "hinweis": "Dein Rechteck ist ein Quadrat."}, {"name": "Fläche 36 cm²", "pruefe": ["=", ["produkt", "$alle"], 36], "zeige": ["produkt", "$alle"], "hinweis": "Dein Rechteck hat {} cm²."}], "beispiel": [9, 4], "gut": [[36, 1], [3, 12]], "gegenbeispiele": [{"werte": [-6, -6], "verletzt": "beide Seiten größer als 0"}, {"werte": [6, 6], "verletzt": "kein Quadrat"}, {"werte": [9, 5], "verletzt": "Fläche 36 cm²"}]}, "h": "Länge mal Breite soll 36 ergeben.", "w": "Zum Beispiel 9 cm mal 4 cm, 12 cm mal 3 cm oder 18 cm mal 2 cm.", "form": "viele_antworten", "zaehlt": "ja", "r": 604}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne eine Fläche in ganzen dm², die größer als 2,5 m² und kleiner als 2,6 m² ist.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "größer als 2,5 m²", "pruefe": [">", "$1", 250], "zeige": "$1", "hinweis": "Deine Fläche ist {} dm²."}, {"name": "kleiner als 2,6 m²", "pruefe": ["<", "$1", 260], "zeige": "$1", "hinweis": "Deine Fläche ist {} dm²."}], "beispiel": [255], "gut": [[251], [259]], "gegenbeispiele": [{"werte": [25], "verletzt": "größer als 2,5 m²"}, {"werte": [260], "verletzt": "kleiner als 2,6 m²"}, {"werte": [2550], "verletzt": "kleiner als 2,6 m²"}, {"werte": [250], "verletzt": "größer als 2,5 m²"}]}, "h": "Rechne beide Grenzen in dm² um.", "w": "2,5 m² = 250 dm² und 2,6 m² = 260 dm². Es passt jede Zahl von 251 bis 259.", "form": "viele_antworten", "zaehlt": "ja", "r": 605}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Nenne Länge und Breite (ganze Zentimeter) eines Rechtecks mit dem Umfang 24 cm und einer Fläche von weniger als 30 cm².", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "beide Seiten größer als 0", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Deine kürzere Seite ist {} cm."}, {"name": "Umfang 24 cm", "pruefe": ["=", ["*", 2, ["summe", "$alle"]], 24], "zeige": ["*", 2, ["summe", "$alle"]], "hinweis": "Dein Rechteck hat den Umfang {} cm."}, {"name": "Fläche weniger als 30 cm²", "pruefe": ["<", ["produkt", "$alle"], 30], "zeige": ["produkt", "$alle"], "hinweis": "Dein Rechteck hat {} cm²."}], "beispiel": [10, 2], "gut": [[11, 1], [3, 9]], "gegenbeispiele": [{"werte": [0, 12], "verletzt": "beide Seiten größer als 0"}, {"werte": [10, 3], "verletzt": "Umfang 24 cm"}, {"werte": [6, 6], "verletzt": "Fläche weniger als 30 cm²"}, {"werte": [8, 4], "verletzt": "Fläche weniger als 30 cm²"}]}, "h": "Länge plus Breite ist der halbe Umfang.", "w": "Länge plus Breite ist 12 cm. Schmale Rechtecke haben wenig Fläche: 10 · 2 = 20 cm², 9 · 3 = 27 cm², 11 · 1 = 11 cm².", "form": "viele_antworten", "zaehlt": "ja", "r": 606}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Aus einem Rechteck von 10 cm mal 6 cm wird an einer Ecke ein kleineres Rechteck herausgeschnitten (ganze Zentimeter). Es bleibt eine L-förmige Fläche von genau 48 cm² übrig. Beide Seiten des Stücks sind kürzer als die Seiten des großen Rechtecks. Nenne im ersten Feld die Länge (waagrecht, kleiner als 10 cm) und im zweiten Feld die Breite (senkrecht, kleiner als 6 cm) des herausgeschnittenen Stücks.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "Stück lässt eine L-Form übrig", "pruefe": ["und", [">=", "$1", 1], ["<", "$1", 10], [">=", "$2", 1], ["<", "$2", 6]], "hinweis": "Dein Stück muss in der Ecke liegen und beide Seiten müssen kürzer sein als die des großen Rechtecks: Länge 1 bis 9 cm, Breite 1 bis 5 cm."}, {"name": "übrig bleiben 48 cm²", "pruefe": ["=", ["-", 60, ["*", "$1", "$2"]], 48], "zeige": ["-", 60, ["*", "$1", "$2"]], "hinweis": "Bei dir bleiben {} cm² übrig."}], "beispiel": [4, 3], "gut": [[6, 2], [3, 4]], "gegenbeispiele": [{"werte": [12, 1], "verletzt": "Stück lässt eine L-Form übrig"}, {"werte": [2, 6], "verletzt": "Stück lässt eine L-Form übrig"}, {"werte": [5, 2], "verletzt": "übrig bleiben 48 cm²"}]}, "h": "Wie groß ist die ganze Fläche? Wie viel muss also weg?", "w": "Das ganze Rechteck hat 60 cm². Es müssen 12 cm² weg. Länge unter 10 cm, Breite unter 6 cm: 4 cm mal 3 cm, 3 cm mal 4 cm oder 6 cm mal 2 cm. Ein Streifen 2 cm mal 6 cm ginge über die ganze Breite, dann bleibt keine L-Form.", "form": "viele_antworten", "zaehlt": "ja", "r": 607}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "transfer", "y": "bedingung", "f": {"text": "Nenne zwei Rechtecke (ganze Zentimeter) mit gleicher Fläche, aber verschiedenem Umfang. Reihenfolge der Felder: Länge und Breite des ersten, Länge und Breite des zweiten.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "alle Seiten größer als 0", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Deine kürzeste Seite ist {} cm."}, {"name": "gleiche Fläche", "pruefe": ["=", ["*", "$1", "$2"], ["*", "$3", "$4"]], "zeige": ["*", "$1", "$2"], "hinweis": "Dein erstes Rechteck hat {} cm², das zweite nicht."}, {"name": "verschiedener Umfang", "pruefe": ["!=", ["+", "$1", "$2"], ["+", "$3", "$4"]], "zeige": ["*", 2, ["+", "$1", "$2"]], "hinweis": "Beide Rechtecke haben bei dir den Umfang {} cm."}], "beispiel": [6, 2, 4, 3], "gut": [[12, 1, 3, 4]], "gegenbeispiele": [{"werte": [0, 5, 0, 3], "verletzt": "alle Seiten größer als 0"}, {"werte": [6, 2, 4, 4], "verletzt": "gleiche Fläche"}, {"werte": [6, 2, 2, 6], "verletzt": "verschiedener Umfang"}]}, "h": "Suche zwei verschiedene Malaufgaben mit demselben Ergebnis.", "w": "Zum Beispiel 6 · 2 = 12 und 4 · 3 = 12. Umfang: 16 cm und 14 cm.", "form": "viele_antworten", "zaehlt": "ja", "r": 608}]$auf$::jsonb),
    (57, 'geometrie.konstruktion', 618, 7, $auf$[{"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Von einem Dreieck kennst du a = 5 cm, b = 7 cm und den Winkel γ zwischen diesen beiden Seiten. Welcher Kongruenzsatz sichert, dass das Dreieck eindeutig ist?"}, "a": ["SSS", "SWS", "WSW", "SsW"], "o": {"index": 1}, "h": "Wo liegt der Winkel: zwischen den Seiten oder einer Seite gegenüber?", "w": "Zwei Seiten und der Winkel dazwischen: SWS.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 619}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem gleichschenkligen Dreieck hat ein Basiswinkel 72°. Wie groß ist der Winkel an der Spitze?"}, "o": {"wert": 36, "einheit": "°"}, "h": "Es gibt zwei gleich große Basiswinkel.", "w": "Beide Basiswinkel zusammen: 144°. Spitze: 180° − 144° = 36°.", "form": "umkehren", "zaehlt": "ja", "r": 620}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zwei Seiten eines Dreiecks sind 4 cm und 9 cm lang. Die dritte Seite ist eine ganze Zahl von Zentimetern. Wie lang muss sie mindestens sein?"}, "o": {"wert": 6, "einheit": "cm"}, "h": "Die dritte Seite und die 4 cm müssen zusammen länger als 9 cm sein.", "w": "4 cm + x muss größer als 9 cm sein, also x größer als 5 cm. Die kleinste ganze Zahl ist 6.", "form": "umkehren", "zaehlt": "ja", "r": 621}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Du konstruierst ein Dreieck aus c = 6 cm, α = 50° und b = 4 cm (SWS). Welche Reihenfolge führt zum Ziel?"}, "a": ["c zeichnen; Kreis um A mit 4 cm; Kreis um B mit 6 cm", "α zeichnen; c irgendwo anlegen; b messen", "b zeichnen; α im Punkt C antragen; mit B verbinden", "c zeichnen; α im Punkt A antragen; auf dem freien Schenkel 4 cm abtragen; C mit B verbinden"], "o": {"index": 3}, "h": "Beginne mit einer gegebenen Seite. Wo liegt der Winkel α?", "w": "α liegt bei A zwischen c und b. Also: c zeichnen, α in A antragen, 4 cm abtragen ergibt C, dann C mit B verbinden.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 622}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Satz: „Wenn ein Viereck ein Quadrat ist, dann hat es vier rechte Winkel.“ Was gilt für den Kehrsatz?"}, "a": ["Der Kehrsatz stimmt auch.", "Der Kehrsatz ist falsch: Ein Rechteck, das kein Quadrat ist, hat auch vier rechte Winkel.", "Der Kehrsatz ist falsch, weil ein Quadrat keine rechten Winkel hat.", "Der Kehrsatz lautet: „Wenn ein Viereck kein Quadrat ist, hat es keine rechten Winkel.“"], "o": {"index": 1}, "h": "Vertausche Wenn und Dann. Suche dann ein Gegenbeispiel.", "w": "Kehrsatz: „Wenn ein Viereck vier rechte Winkel hat, dann ist es ein Quadrat.“ Ein Rechteck mit 3 cm und 5 cm widerlegt ihn.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 623}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "bedingung", "f": {"text": "Nenne die drei Innenwinkel eines gleichschenkligen Dreiecks, das nicht gleichseitig ist. Alle Winkel sollen spitz und ganze Grad sein.", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "alle Winkel spitz", "pruefe": ["und", [">", ["min", "$alle"], 0], ["<", ["max", "$alle"], 90]], "zeige": ["max", "$alle"], "hinweis": "Dein größter Winkel hat {}°."}, {"name": "Winkel eines Dreiecks", "pruefe": ["=", ["summe", "$alle"], 180], "zeige": ["summe", "$alle"], "hinweis": "Deine Winkel ergeben zusammen {}°."}, {"name": "gleichschenklig", "pruefe": ["oder", ["=", "$1", "$2"], ["=", "$2", "$3"], ["=", "$1", "$3"]], "hinweis": "Bei dir sind keine zwei Winkel gleich groß."}, {"name": "nicht gleichseitig", "pruefe": ["nicht", ["und", ["=", "$1", "$2"], ["=", "$2", "$3"]]], "hinweis": "Dein Dreieck ist gleichseitig."}], "beispiel": [70, 70, 40], "gut": [[50, 80, 50], [89, 2, 89]], "gegenbeispiele": [{"werte": [100, 40, 40], "verletzt": "alle Winkel spitz"}, {"werte": [70, 70, 50], "verletzt": "Winkel eines Dreiecks"}, {"werte": [50, 60, 70], "verletzt": "gleichschenklig"}, {"werte": [60, 60, 60], "verletzt": "nicht gleichseitig"}]}, "h": "Welche Winkel sind im gleichschenkligen Dreieck gleich groß?", "w": "Zwei Basiswinkel sind gleich, zum Beispiel 70° und 70°. Für die Spitze bleiben 40°.", "form": "viele_antworten", "zaehlt": "ja", "r": 624}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "Zwei Seiten eines Dreiecks sind 5 cm und 8 cm lang. Nenne eine dritte Seitenlänge in cm, mit der sich das Dreieck konstruieren lässt und die länger ist als jede der beiden anderen.", "felder": [{"art": "rational"}]}, "o": {"bedingungen": [{"name": "länger als beide anderen Seiten", "pruefe": [">", "$1", 8], "zeige": "$1", "hinweis": "Deine Seite ist {} cm lang."}, {"name": "Dreieck lässt sich konstruieren", "pruefe": ["<", "$1", 13], "zeige": "$1", "hinweis": "Deine Seite ist {} cm lang. Die beiden anderen sind zusammen nur 13 cm lang."}], "beispiel": [10], "gut": [["8,5"], ["12,9"]], "gegenbeispiele": [{"werte": [7], "verletzt": "länger als beide anderen Seiten"}, {"werte": [13], "verletzt": "Dreieck lässt sich konstruieren"}, {"werte": [20], "verletzt": "Dreieck lässt sich konstruieren"}]}, "h": "Zwei Seiten zusammen müssen länger sein als die dritte.", "w": "5 cm + 8 cm = 13 cm. Die dritte Seite muss kürzer als 13 cm sein und soll länger als 8 cm sein, zum Beispiel 10 cm.", "form": "viele_antworten", "zaehlt": "ja", "r": 625}]$auf$::jsonb),
    (67, 'groessen.proportional', 633, 20, $auf$[{"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "6 Äpfel kosten 3 €. In Cent sind das ① Cent. Für einen Apfel zahlt man ① : 6 = ② Cent. Für 4 Äpfel zahlt man 4 · ② = ③ Cent.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [300, 50, 200]}, "h": "Wert durch Anzahl ergibt den Preis für 1 Stück.", "w": "3 € = 300 Cent. 300 : 6 = 50 Cent für einen Apfel. 4 · 50 = 200 Cent.", "form": "lueckenweg", "zaehlt": "nein", "r": 634}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "3 Hefte kosten 4,50 €. Gesucht ist der Preis für 5 Hefte. Emil rechnet: 4,50 € + 2 € = 6,50 €. Was ist falsch?"}, "a": ["Er zählt für 2 Hefte einfach 2 € dazu, statt erst den Preis für 1 Heft zu berechnen.", "Er müsste 4,50 € · 5 rechnen.", "Nichts.", "Er müsste 4,50 € − 2 € rechnen."], "o": {"index": 0}, "h": "Was kostet 1 Heft?", "w": "1 Heft kostet 4,50 € : 3 = 1,50 €. 5 Hefte kosten 5 · 1,50 € = 7,50 €.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 635}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Bei welcher Aufgabe darfst du mit dem Dreisatz rechnen?"}, "a": ["3 kg Kartoffeln kosten 4,50 €; jedes Kilogramm kostet gleich viel. Was kosten 5 kg?", "Ein Kind ist mit 6 Jahren 1,20 m groß. Wie groß ist es mit 12 Jahren?", "Ein Lied dauert 3 Minuten, wenn ein Kind es singt. Wie lange dauert es, wenn 4 Kinder es zusammen singen?"], "o": {"index": 0}, "h": "Prüfe: doppelte Menge, doppelter Wert?", "w": "Weil jedes Kilogramm gleich viel kostet, kosten doppelt so viele Kartoffeln doppelt so viel. Ohne diese Angabe (Mengenrabatt) dürfte man auch hier nicht rechnen. Größe und Liedlänge verdoppeln sich nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 636}, {"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "12 Flaschen kosten 18 €. Gesucht ist der Preis für 8 Flaschen. Welche Zwischenmenge ist geschickt?"}, "a": ["5 Flaschen", "10 Flaschen", "7 Flaschen", "4 Flaschen"], "o": {"index": 3}, "h": "Die Zwischenmenge soll in 12 und in 8 passen.", "w": "4 passt in beide: 12 : 3 = 4 und 4 · 2 = 8. Also 18 € : 3 = 6 €, dann 6 € · 2 = 12 €.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 637}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "4 Brötchen kosten 2,40 €. Wie viel kosten 7? Erst auf 1 Brötchen: 240 Cent : 4 = ① Cent. Dann auf 7 Brötchen: ① Cent · 7 = ② Cent.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [60, 420]}, "h": "Erst auf 1 Stück schließen, dann auf das Gesuchte.", "w": "240 : 4 = 60 Cent. 60 · 7 = 420 Cent = 4,20 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 638}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 2, "g": "darstellung", "y": "luecken", "f": {"text": "Ergänze die Dreisatz-Tabelle. Die Preise stehen in Cent.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke ein Preis in Cent.", "grafik": {"typ": "tabelle", "kopf": ["Karten", "8", "1", "5"], "zeilen": [["Preis (Cent)", "1200", "①", "②"]]}}, "o": {"werte": [150, 750]}, "h": "Was du oben tust, tust du auch unten.", "w": "Geteilt durch 8: 1 200 : 8 = 150 Cent. Mal 5: 150 · 5 = 750 Cent.", "form": "bruecke", "zaehlt": "ja", "r": 639}, {"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "6 kg kosten 15 €. Gesucht ist der Preis für 9 kg. Weg A über 1 kg: 15 € : 6 = 2,50 €, dann mal 9. Weg B über 3 kg: 3 kg kosten ① Cent, 9 kg kosten ② Cent.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke ein Preis in Cent."}, "o": {"werte": [750, 2250]}, "h": "Von 6 nach 3 teilst du durch 2. Von 3 nach 9 nimmst du mal 3.", "w": "3 kg: 15 € : 2 = 7,50 €. 9 kg: 7,50 € · 3 = 22,50 €. Weg A: 2,50 € · 9 = 22,50 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 640}, {"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Stift kostet 0,80 €. Für wie viele Stifte reichen 12 €?"}, "o": {"wert": 15}, "h": "Rechne in Cent. Wie oft passt der Preis für 1 Stift in 12 €?", "w": "1 200 Cent : 80 Cent = 15 Stifte.", "form": "umkehren", "zaehlt": "ja", "r": 641}, {"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Packung A: 6 Riegel für 2,40 €. Packung B: 10 Riegel für 3,50 €. Bei welcher Packung ist ein Riegel billiger, und um wie viel?"}, "a": ["bei A, um 5 Cent", "bei B, um 5 Cent", "bei A, um 1,10 €", "bei beiden gleich"], "o": {"index": 1}, "h": "Berechne für jede Packung den Preis für 1 Riegel.", "w": "A: 240 Cent : 6 = 40 Cent. B: 350 Cent : 10 = 35 Cent. Bei B ist ein Riegel 5 Cent billiger.", "form": "bruecke", "zaehlt": "ja", "r": 642}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "5 Liter Saft kosten 8 €. Wie viele Liter bekommt man für 20 €?"}, "o": {"wert": 12.5, "einheit": "Liter"}, "h": "Wie viele Liter bekommt man für 1 €? Oder: Wievielmal so viel Geld ist es?", "w": "20 € sind 2,5-mal so viel wie 8 €. Also 2,5 · 5 Liter = 12,5 Liter.", "form": "umkehren", "zaehlt": "ja", "r": 643}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Maler streicht eine Wand in 3 Stunden. Alle Maler arbeiten gleich schnell, und die Arbeit lässt sich beliebig aufteilen. Jule rechnet: „Dann brauchen 2 Maler 6 Stunden.“ Was ist an Jules Rechnung falsch?"}, "a": ["Nichts, Jule hat recht.", "Zwei Maler brauchen auch 3 Stunden.", "Bei doppelter Leistung halbiert sich die Zeit: Zwei Maler brauchen 1,5 Stunden, nicht 6.", "Zwei Maler brauchen 5 Stunden."], "o": {"index": 2}, "h": "Wenn doppelt so viele Maler arbeiten: Wird die Zeit länger oder kürzer?", "w": "Bei gleich schnellen Malern und teilbarer Arbeit gilt: doppelte Leistung, halbe Zeit. Dreisatz: 1 Maler braucht 3 Stunden, 2 Maler brauchen 3 : 2 = 1,5 Stunden. Jule hat die Zeit verdoppelt statt halbiert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 644}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Becken verliert gleichmäßig 3 Liter Wasser pro Stunde. Jetzt sind 50 Liter darin. Nach wie vielen Stunden sind es noch 32 Liter?"}, "o": {"wert": 6, "einheit": "h"}, "h": "Wie viele Liter müssen abfließen?", "w": "Es fließen 50 − 32 = 18 Liter ab. 18 : 3 = 6 Stunden.", "form": "umkehren", "zaehlt": "ja", "r": 645}, {"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "15 Hefte kosten 9 €. Wie viele Hefte bekommt man für 6 €?"}, "o": {"wert": 10}, "h": "Suche einen Zwischenbetrag, der in 9 € und in 6 € passt.", "w": "Für 3 € gibt es 15 : 3 = 5 Hefte. Für 6 € gibt es 2 · 5 = 10 Hefte.", "form": "umkehren", "zaehlt": "ja", "r": 646}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "Die Temperatur fällt in 5 Stunden gleichmäßig von 12 °C auf 2 °C. Nico gibt als Änderungsrate „2 °C pro Stunde“ an. Wie lautet die Änderungsrate richtig? Gib die Zahl mit Vorzeichen an."}, "o": {"wert": -2}, "h": "Nimmt die Größe zu oder ab?", "w": "Änderung: 2 − 12 = −10 °C. Geteilt durch 5 Stunden: −2 °C pro Stunde. Das Minus zeigt: Es wird kälter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 647}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Für 4 Personen braucht ein Rezept 300 g Mehl. Im Schrank ist 1 kg Mehl. Für wie viele Personen reicht das höchstens?"}, "o": {"wert": 13}, "h": "Wie viel Mehl braucht eine Person? Rechne das Kilogramm in Gramm um.", "w": "Eine Person: 300 g : 4 = 75 g. 1 000 g : 75 g = 13, Rest 25 g. Es reicht für 13 Personen.", "form": "anwenden", "zaehlt": "ja", "r": 648}, {"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Ein Stück kostet mindestens 30 und höchstens 40 Cent. Nenne eine Stückzahl größer als 1 und einen passenden Gesamtpreis in Cent.", "felder": [{"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "mehr als 1 Stück", "pruefe": [">", "$1", 1], "zeige": "$1", "hinweis": "Deine Stückzahl ist {}."}, {"name": "Stückpreis mindestens 30 und höchstens 40 Cent", "pruefe": ["und", [">=", "$2", ["*", 30, "$1"]], ["<=", "$2", ["*", 40, "$1"]]], "zeige": ["/", "$2", "$1"], "hinweis": "Bei dir kostet ein Stück {} Cent."}], "beispiel": [4, 140], "gut": [[2, 60], [10, 400]], "gegenbeispiele": [{"werte": [1, 35], "verletzt": "mehr als 1 Stück"}, {"werte": [4, 200], "verletzt": "Stückpreis mindestens 30 und höchstens 40 Cent"}, {"werte": [5, 100], "verletzt": "Stückpreis mindestens 30 und höchstens 40 Cent"}]}, "h": "Gesamtpreis durch Stückzahl ergibt den Preis für 1 Stück.", "w": "Zum Beispiel 4 Stück für 140 Cent: 140 : 4 = 35 Cent je Stück.", "form": "viele_antworten", "zaehlt": "ja", "r": 649}, {"l": "dreisatz", "t": "dreisatz", "p": "uebung", "s": 2, "g": "umkehr", "y": "bedingung", "f": {"text": "4 kg Äpfel kosten 10 €. Nenne eine andere Menge in kg und ihren Preis in Euro. Der Preis soll keine ganze Zahl sein.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "andere Menge, größer als 0", "pruefe": ["und", [">", "$1", 0], ["!=", "$1", 4]], "zeige": "$1", "hinweis": "Deine Menge ist {} kg."}, {"name": "Preis passt zur Menge", "pruefe": ["=", ["*", 4, "$2"], ["*", 10, "$1"]], "zeige": ["/", "$2", "$1"], "hinweis": "Bei dir kostet 1 kg {} €."}, {"name": "Preis ist keine ganze Zahl", "pruefe": ["nicht", ["ganzzahlig", "$2"]], "zeige": "$2", "hinweis": "Dein Preis ist {} € – das ist eine ganze Zahl."}], "beispiel": [3, "7,5"], "gut": [[1, "2,5"], [5, "12,5"]], "gegenbeispiele": [{"werte": [4, 10], "verletzt": "andere Menge, größer al