e": ["=", ["-", "$2", "$1"], ["*", -4, "$3"]], "zeige": ["/", ["-", "$2", "$1"], "$3"], "hinweis": "Deine Änderungsrate ist {} pro Stunde."}], "beispiel": [20, 8, 3], "gut": [[0, -8, 2], [100, 60, 10]], "gegenbeispiele": [{"werte": [20, 16, 1], "verletzt": "Zeitspanne größer als 1"}, {"werte": [8, 20, 3], "verletzt": "Änderungsrate ist −4"}, {"werte": [20, 8, 4], "verletzt": "Änderungsrate ist −4"}]}, "h": "Änderungsrate ist Änderung geteilt durch Zeitspanne.", "w": "In 3 Stunden muss die Größe um 12 abnehmen, zum Beispiel von 20 auf 8.", "form": "viele_antworten", "zaehlt": "ja", "r": 652}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "bedingung", "f": {"text": "3 Kugeln Eis kosten 3,60 €. Du hast 10 €. Nenne eine Zahl von Kugeln, nach deren Kauf dir mehr als 2 €, aber weniger als 5 € bleiben.", "felder": [{"art": "ganz"}]}, "o": {"bedingungen": [{"name": "mindestens 1 Kugel", "pruefe": [">=", "$1", 1], "zeige": "$1", "hinweis": "Deine Zahl ist {}."}, {"name": "es bleiben mehr als 2 €", "pruefe": [">", ["/", ["-", 1000, ["*", 120, "$1"]], 100], 2], "zeige": ["/", ["-", 1000, ["*", 120, "$1"]], 100], "hinweis": "Dir bleiben {} €."}, {"name": "es bleiben weniger als 5 €", "pruefe": ["<", ["/", ["-", 1000, ["*", 120, "$1"]], 100], 5], "zeige": ["/", ["-", 1000, ["*", 120, "$1"]], 100], "hinweis": "Dir bleiben {} €."}], "beispiel": [5], "gut": [[6]], "gegenbeispiele": [{"werte": [0], "verletzt": "mindestens 1 Kugel"}, {"werte": [7], "verletzt": "es bleiben mehr als 2 €"}, {"werte": [4], "verletzt": "es bleiben weniger als 5 €"}]}, "h": "Was kostet eine Kugel?", "w": "Eine Kugel kostet 1,20 €. 5 Kugeln kosten 6 €, es bleiben 4 €. Auch 6 Kugeln passen (es bleiben 2,80 €).", "form": "viele_antworten", "zaehlt": "ja", "r": 653}]$auf$::jsonb),
    (92, 'geometrie.winkelsaetze', 658, 14, $auf$[{"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Geraden schneiden sich. α = 48°. Der Nebenwinkel β von α hat 180° − 48° = ①°. Der Scheitelwinkel von β ist gleich groß. Beide Winkel β zusammen haben 2 · ① = ②°. Alle vier Winkel: ② + 2 · 48° = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [132, 264, 360]}, "h": "Scheitelwinkel sind gleich groß. Nebenwinkel ergeben zusammen 180°.", "w": "β = 132°. 2 · 132 = 264. 264 + 96 = 360.", "form": "lueckenweg", "zaehlt": "nein", "r": 659}, {"l": "stufen_wechsel", "t": "stufen_wechsel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "g ∥ h. Bei S ist der Winkel rechts oberhalb 70° groß. Wie groß ist sein Stufenwinkel bei T, und wie groß ist der Winkel bei T links oberhalb?", "schablone": "Stufenwinkel: □°; links oberhalb: □°", "hinweis": "Je Lücke ein Winkel in Grad.", "grafik": {"typ": "figur", "punkte": {"S": [3.092, 3.0], "_SR": [4.692, 3.0], "_SL": [1.492, 3.0], "_SU": [3.639, 4.504], "_SD": [2.545, 1.496], "T": [2.0, 0.0], "_TR": [3.6, 0.0], "_TL": [0.4, 0.0], "_TU": [2.547, 1.504], "_TD": [1.453, -1.504], "_g1": [-1.0, 3.0], "_g2": [6.0920000000000005, 3.0], "_h1": [-1.0, 0.0], "_h2": [6.0920000000000005, 0.0], "_k1": [1.453, -1.504], "_k2": [3.639, 4.504]}, "linien": [["_g1", "_g2", "g"], ["_h1", "_h2", "h"], ["_k1", "_k2", "k"]], "winkel": [["S", "_SR", "_SU", "70°"], ["T", "_TR", "_TU", "?"], ["T", "_TU", "_TL", "?"]]}}, "o": {"werte": [70, 110]}, "h": "Der Stufenwinkel liegt bei T an derselben Stelle wie bei S.", "w": "Stufenwinkel an Parallelen sind gleich: 70°. Der Winkel daneben ist sein Nebenwinkel: 110°.", "form": "bruecke", "zaehlt": "ja", "r": 660}, {"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Eine Gerade schneidet g unter 64°. Der Stufenwinkel dazu an der Geraden h hat 66°. Was folgt?"}, "a": ["g und h sind parallel.", "g und h sind nicht parallel.", "g und h stehen senkrecht aufeinander.", "Dazu lässt sich nichts sagen."], "o": {"index": 1}, "h": "Was gilt für Stufenwinkel an Parallelen?", "w": "An Parallelen sind Stufenwinkel gleich groß. 64° und 66° sind verschieden, also sind g und h nicht parallel.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 661}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Mit welchen Fliesen allein kann man einen Boden NICHT lückenlos auslegen?"}, "a": ["gleichseitige Dreiecke (Innenwinkel 60°)", "Quadrate (90°)", "regelmäßige Fünfecke (108°)", "regelmäßige Sechsecke (120°)"], "o": {"index": 2}, "h": "An einer Ecke müssen die Winkel zusammen 360° ergeben.", "w": "360° ist durch 60°, 90° und 120° teilbar, aber nicht durch 108°. Drei Fünfecke ergeben 324°, vier schon 432°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 662}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Dreieck ist β doppelt so groß wie α, und γ = 60°. Wie groß ist α?"}, "o": {"wert": 40, "einheit": "°"}, "h": "α und β zusammen sind drei „α“.", "w": "α + 2α + 60° = 180°, also 3α = 120° und α = 40°.", "form": "umkehren", "zaehlt": "ja", "r": 663}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "luecken", "f": {"text": "Dreieck mit α = 50° und β = 65°. Gesucht ist der Außenwinkel bei C. Weg A: γ = 180° − 50° − 65° = ①°, Außenwinkel = 180° − ①° = ②°. Weg B: 50° + 65°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl.", "grafik": {"typ": "figur", "punkte": {"A": [0, 0], "B": [6, 0], "C": [3.857, 4.596]}, "linien": [["A", "B"], ["B", "C"], ["C", "A"]], "winkel": [["A", "B", "C", "α"], ["B", "C", "A", "β"], ["C", "A", "B", "γ"]]}}, "o": {"werte": [65, 115]}, "h": "Der Außenwinkel ist so groß wie die beiden anderen Innenwinkel zusammen.", "w": "γ = 65°. Außenwinkel: 180° − 65° = 115°. Weg B: 50° + 65° = 115°.", "form": "zwei_wege", "zaehlt": "ja", "r": 664}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Vieleck hat die Winkelsumme 900°. Wie viele Ecken hat es?"}, "o": {"wert": 7}, "h": "Die Winkelsumme ist (n − 2) · 180°. Rechne rückwärts.", "w": "900° : 180° = 5. Das ist n − 2, also n = 7.", "form": "umkehren", "zaehlt": "ja", "r": 665}, {"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Gerade schneidet g unter 115°. An der Geraden h wird der Nebenwinkel des zugehörigen Wechselwinkels gemessen. Wie groß muss er sein, damit g und h parallel sind?"}, "o": {"wert": 65, "einheit": "°"}, "h": "Wie groß muss der Wechselwinkel selbst sein?", "w": "Bei Parallelen ist der Wechselwinkel auch 115°. Sein Nebenwinkel hat 180° − 115° = 65°.", "form": "umkehren", "zaehlt": "ja", "r": 666}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 3, "g": "fehler", "y": "zahl", "f": {"text": "In einem Dreieck ist der Außenwinkel bei C 130° groß, und α = 55°. Mia rechnet: β = 180° − 130° = 50°. Wie groß ist β wirklich?"}, "o": {"wert": 75, "einheit": "°"}, "h": "Was hat Mia mit 180° − 130° wirklich berechnet?", "w": "180° − 130° = 50° ist der Innenwinkel γ. Der Außenwinkel ist α + β, also β = 130° − 55° = 75°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 667}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "g ∥ h. Die Gerade k schneidet g in S und h in T. Bei S ist der Winkel links oberhalb 125° groß. Eine zweite Gerade m durch T bildet mit h rechts oberhalb von T den Winkel 30°. Wie groß ist der Winkel bei T zwischen m und k?", "grafik": {"typ": "figur", "punkte": {"S": [4.101, 3.0], "_SR": [5.701, 3.0], "_SL": [2.501, 3.0], "_SU": [5.019, 4.311], "_SD": [3.183, 1.689], "T": [2.0, 0.0], "_TR": [3.6, 0.0], "_TL": [0.4, 0.0], "_TU": [2.918, 1.311], "_TD": [1.082, -1.311], "_g1": [-1.0, 3.0], "_g2": [7.101, 3.0], "_h1": [-1.0, 0.0], "_h2": [7.101, 0.0], "_k1": [1.082, -1.311], "_k2": [5.019, 4.311], "_m1": [4.598, 1.5], "_m2": [0.701, -0.75]}, "linien": [["_g1", "_g2", "g"], ["_h1", "_h2", "h"], ["_k1", "_k2", "k"], ["_m1", "_m2", "m"]], "winkel": [["S", "_SU", "_SL", "125°"], ["T", "_TR", "_m1", "30°"]]}}, "o": {"wert": 25, "einheit": "°"}, "h": "Bestimme zuerst den Winkel bei T rechts oberhalb zwischen h und k. Welcher Winkelsatz hilft?", "w": "Bei S rechts oberhalb: 180° − 125° = 55° (Nebenwinkel). Bei T rechts oberhalb ebenfalls 55° (Stufenwinkel). Davon gehen 30° ab: 25°.", "form": "umkehren", "zaehlt": "ja", "r": 668}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Beweis der Winkelsumme im Dreieck ABC: Durch C wird die Parallele p zu AB gezeichnet. D ist der Punkt auf p, für den der Strahl CD parallel und gleichgerichtet zum Strahl BA verläuft. Welcher Satz begründet, dass der Winkel ∠DCA so groß ist wie α = ∠CAB?"}, "a": ["Wechselwinkel an Parallelen sind gleich groß.", "Scheitelwinkel sind gleich groß.", "Nebenwinkel ergeben 180°.", "Die Winkelsumme im Dreieck ist 180°."], "o": {"index": 0}, "h": "Welche zwei Geraden sind parallel, und welche Gerade schneidet beide?", "w": "AB und p sind parallel, die Gerade AC schneidet beide. Der Strahl CD zeigt in dieselbe Richtung wie BA, also liegen ∠CAB und ∠DCA auf verschiedenen Seiten von AC und bei verschiedenen Parallelen: Es sind Wechselwinkel.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 669}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 1, "g": "direkt", "y": "bedingung", "f": {"text": "Nenne die drei Innenwinkel eines stumpfwinkligen Dreiecks (ganze Grad).", "felder": [{"art": "ganz"}, {"art": "ganz"}, {"art": "ganz"}]}, "o": {"bedingungen": [{"name": "jeder Winkel größer als 0°", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Dein kleinster Winkel hat {}°."}, {"name": "Winkel eines Dreiecks", "pruefe": ["=", ["summe", "$alle"], 180], "zeige": ["summe", "$alle"], "hinweis": "Deine Winkel ergeben zusammen {}°."}, {"name": "ein Winkel ist stumpf", "pruefe": [">", ["max", "$alle"], 90], "zeige": ["max", "$alle"], "hinweis": "Dein größter Winkel hat {}°."}], "beispiel": [100, 50, 30], "gut": [[91, 88, 1]], "gegenbeispiele": [{"werte": [100, 90, -10], "verletzt": "jeder Winkel größer als 0°"}, {"werte": [100, 50, 40], "verletzt": "Winkel eines Dreiecks"}, {"werte": [60, 60, 60], "verletzt": "ein Winkel ist stumpf"}, {"werte": [90, 45, 45], "verletzt": "ein Winkel ist stumpf"}]}, "h": "Wie groß ist die Winkelsumme im Dreieck? Was heißt stumpf?", "w": "Zusammen 180°, einer größer als 90°. Zum Beispiel 100°, 50° und 30°.", "form": "viele_antworten", "zaehlt": "ja", "r": 670}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "bedingung", "f": {"text": "Nenne die Eckenzahl eines regelmäßigen Vielecks, dessen Innenwinkel größer als 130° ist, und diesen Innenwinkel in Grad.", "felder": [{"art": "ganz"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "mindestens 3 Ecken", "pruefe": [">=", "$1", 3], "zeige": "$1", "hinweis": "Deine Eckenzahl ist {}."}, {"name": "Innenwinkel passt zur Eckenzahl", "pruefe": ["=", ["*", "$1", "$2"], ["*", ["-", "$1", 2], 180]], "zeige": ["/", ["*", ["-", "$1", 2], 180], "$1"], "hinweis": "Zu deiner Eckenzahl gehört der Innenwinkel {}°."}, {"name": "Innenwinkel größer als 130°", "pruefe": [">", "$2", 130], "zeige": "$2", "hinweis": "Dein Innenwinkel hat {}°."}], "beispiel": [8, 135], "gut": [[9, 140], [10, 144], [12, 150]], "gegenbeispiele": [{"werte": [2, 0], "verletzt": "mindestens 3 Ecken"}, {"werte": [8, 140], "verletzt": "Innenwinkel passt zur Eckenzahl"}, {"werte": [6, 120], "verletzt": "Innenwinkel größer als 130°"}]}, "h": "Winkelsumme (n − 2) · 180°, geteilt durch die Zahl der Ecken.", "w": "Achteck: 6 · 180° = 1 080°, geteilt durch 8 sind 135°. Auch 9 Ecken (140°) oder 10 Ecken (144°) passen.", "form": "viele_antworten", "zaehlt": "ja", "r": 671}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 3, "g": "parameter", "y": "bedingung", "f": {"text": "Ein Dreieck hat bei C den Außenwinkel 110°. Nenne α und β (beide größer als 0°) so, dass α mehr als doppelt so groß ist wie β.", "felder": [{"art": "rational"}, {"art": "rational"}]}, "o": {"bedingungen": [{"name": "beide größer als 0°", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Dein kleinerer Winkel hat {}°."}, {"name": "passt zum Außenwinkel 110°", "pruefe": ["=", ["summe", "$alle"], 110], "zeige": ["summe", "$alle"], "hinweis": "Dein α und dein β ergeben zusammen {}°."}, {"name": "α mehr als doppelt so groß wie β", "pruefe": [">", "$1", ["*", 2, "$2"]], "zeige": ["*", 2, "$2"], "hinweis": "Das Doppelte von deinem β ist {}°."}], "beispiel": [80, 30], "gut": [[100, 10], ["74,5", "35,5"]], "gegenbeispiele": [{"werte": [110, 0], "verletzt": "beide größer als 0°"}, {"werte": [80, 40], "verletzt": "passt zum Außenwinkel 110°"}, {"werte": [70, 40], "verletzt": "α mehr als doppelt so groß wie β"}]}, "h": "Wie hängt der Außenwinkel mit α und β zusammen?", "w": "α + β = 110°. Zum Beispiel α = 80° und β = 30°: 80° ist mehr als 60°.", "form": "viele_antworten", "zaehlt": "ja", "r": 672}]$auf$::jsonb),
    (306, 'geometrie.konstruktion_teil2', 632, 2, $auf$[{"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 1, "g": "direkt", "y": "auswahl", "f": {"text": "Ein Parallelogramm ABCD ist durch 3 unabhängige Stücke festgelegt. Du kennst die Seite a = AB und den Winkel α bei A. Welche weitere Angabe fehlt noch?"}, "a": ["die Länge der Seite CD, die a gegenüberliegt", "der Winkel bei C, der α gegenüberliegt", "die Länge der zweiten benachbarten Seite b = AD", "der Winkel β bei B"], "o": {"index": 2}, "h": "Was folgt aus a und α schon von selbst? Gegenüberliegende Seiten und Winkel sind gleich, Nachbarwinkel ergeben 180°.", "w": "Die Seite CD ist so lang wie a, der Winkel bei C so groß wie α, und β = 180° − α. Das sind keine neuen Angaben. Es fehlt eine zweite Seite: die Länge von b = AD.", "form": "bruecke", "zaehlt": "ja", "r": 633}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Parallelogramm ist ein Winkel um 30° größer als sein Nachbarwinkel. Wie groß ist der größere der beiden?"}, "o": {"wert": 105, "einheit": "°"}, "h": "Benachbarte Winkel im Parallelogramm ergeben 180°.", "w": "x + (x + 30°) = 180°, also x = 75°. Der größere hat 105°.", "form": "umkehren", "zaehlt": "ja", "r": 634}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 127 then fehler := fehler || ('zusammen ' || gesamt || ' statt 127')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (17, 22, 49, 51, 57, 67, 92, 306) group by 1 order by 1;
